-- Name: comprobar_estadopedido(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.comprobar_estadopedido() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.estado NOT IN (
        'Entregado',
        'Enviado',
        'Pendiente',
        'En preparacion',
        'Cancelado'
    ) THEN
        RAISE EXCEPTION
        'El estado del pedido no es válido';
    END IF;

    RETURN NEW;
END;
$$;


--
-- TOC entry 242 (class 1255 OID 17592)
-- Name: comprobar_fechapedido(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.comprobar_fechapedido() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.fecha > CURRENT_DATE THEN
        RAISE EXCEPTION
        'La fecha del pedido no puede ser futura';
    END IF;
			
    RETURN NEW;
END;
$$;


--
-- TOC entry 241 (class 1255 OID 17590)
-- Name: comprobar_modelo(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.comprobar_modelo() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.precio <= 0 THEN
        RAISE EXCEPTION
        'El precio del modelo debe ser mayor que 0';
    END IF;

    IF NEW.stock <= 0 THEN
        RAISE EXCEPTION
        'El stock del modelo debe ser mayor que 0';
    END IF;

    RETURN NEW;
END;
$$;


--
-- TOC entry 246 (class 1255 OID 17608)
-- Name: comprobar_preciototal(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.comprobar_preciototal() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    precioM NUMERIC;
    lineaID TEXT;
    modeloID TEXT;
    cantidadL NUMERIC;
BEGIN

    IF TG_TABLE_NAME = 'Linea de pedido' THEN
        lineaID := NEW.id_linea;
        cantidadL := NEW.cantidad;

        SELECT m.precio
        INTO precioM
        FROM public."Pedido" p
        JOIN public."Modelo" m
            ON m.id_modelo = p."id_modelo_Modelo"
        WHERE p."id_linea_Linea de pedido" = lineaID
        LIMIT 1;

        IF precioM IS NOT NULL THEN
            NEW."PrecioTotal" := cantidadL * precioM;
        END IF;
        RETURN NEW;

    ELSIF TG_TABLE_NAME = 'Pedido' THEN
        SELECT cantidad
        INTO cantidadL
        FROM public."Linea de pedido"
        WHERE id_linea = NEW."id_linea_Linea de pedido";

        SELECT precio
        INTO precioM
        FROM public."Modelo"
        WHERE id_modelo = NEW."id_modelo_Modelo";

        IF cantidadL IS NOT NULL AND precioM IS NOT NULL THEN
            UPDATE public."Linea de pedido"
            SET "PrecioTotal" = cantidadL * precioM
            WHERE id_linea = NEW."id_linea_Linea de pedido";
        END IF;

        RETURN NEW;
    END IF;
    RETURN NULL;
END;
$$;


